<!DOCTYPE html>
<html lang="en"><head><meta charset="utf-8">
<script src="https://cdn.jsdelivr.net/npm/d3@7.9.0/dist/d3.min.js"></script>
<script src="https://cdn.jsdelivr.net/npm/simple-statistics@7.8.8/dist/simple-statistics.min.js"></script>
<style>
  body { margin: 0; padding: 18px 20px; font-family: system-ui, sans-serif; color: #1d2433; background: #fbfaf7; }
  h2 { font-size: 17px; margin: 0 0 2px; }
  .sub { color: #677086; font-size: 13px; margin: 0 0 8px; }
  section { margin-bottom: 18px; }
  .pair { display: flex; gap: 16px; flex-wrap: wrap; }
  .pair > div { flex: 1 1 230px; }
  .cap { font-size: 13px; font-weight: 600; margin: 4px 0; }
  .note { font-size: 13px; color: #677086; }
  svg { display: block; width: 100%; height: auto; overflow: visible; }
  #wait { color: #677086; }
</style></head>
<body>
<div id="wait">Upload a CSV to see the interpretation.</div>
<div id="app" style="display:none">
  <section>
    <h2>Compared with their own first days</h2>
    <p class="sub" id="baseText"></p>
    <svg id="steps" viewBox="0 0 560 190"></svg>
  </section>
  <section>
    <h2>Pain: the same day, or the day after?</h2>
    <p class="sub">Each dot is a day. The line shows the trend.</p>
    <div class="pair">
      <div><div class="cap" id="capSame"></div><svg id="same" viewBox="0 0 260 180"></svg></div>
      <div><div class="cap" id="capNext"></div><svg id="next" viewBox="0 0 260 180"></svg></div>
    </div>
    <p class="note" id="caution"></p>
  </section>
</div>
<script>
const num = (v) => typeof v === 'number' && isFinite(v);
const strength = (r) => Math.abs(r) < 0.2 ? 'hardly linked' : Math.abs(r) < 0.4 ? 'weakly linked' : Math.abs(r) < 0.6 ? 'clearly linked' : 'strongly linked';

window.onBioframe = function (frame) {
  const rows = frame.data.rows;
  document.getElementById('wait').style.display = 'none';
  document.getElementById('app').style.display = 'block';
  drawSteps(rows);
  drawPain(rows);
};

// Weekly average bend, as change from the mean of the first three days.
function drawSteps(rows) {
  const bends = rows.map(r => r.knee_flexion_deg);
  const base = ss.mean(bends.filter(num).slice(0, 3));
  const weeks = d3.range(Math.ceil(rows.length / 7)).map(w => {
    const v = bends.slice(w * 7, w * 7 + 7).filter(num);
    return { w, gain: v.length ? ss.mean(v) - base : null };
  }).filter(d => d.gain !== null);
  document.getElementById('baseText').textContent =
    `Their first days averaged ${Math.round(base)}°. Each step is a week's average bend above that.`;

  const svg = d3.select('#steps').html('');
  const x = d3.scaleBand(weeks.map(d => d.w), [40, 540]).padding(0.08);
  const y = d3.scaleLinear([0, d3.max(weeks, d => d.gain) * 1.15], [160, 15]);
  svg.append('line').attr('x1', 40).attr('x2', 540).attr('y1', 160).attr('y2', 160).attr('stroke', '#c9ccd4');
  svg.append('text').attr('x', 36).attr('y', 164).attr('text-anchor', 'end').attr('font-size', 11).attr('fill', '#677086').text('start');
  svg.selectAll('rect').data(weeks).join('rect')
    .attr('x', d => x(d.w)).attr('width', x.bandwidth())
    .attr('y', d => y(d.gain)).attr('height', d => 160 - y(d.gain))
    .attr('fill', (d, i) => d3.interpolateBlues(0.35 + 0.6 * i / weeks.length)).attr('rx', 3);
  svg.selectAll('.g').data(weeks).join('text')
    .attr('x', d => x(d.w) + x.bandwidth() / 2).attr('y', d => y(d.gain) - 6).attr('text-anchor', 'middle')
    .attr('font-size', 13).attr('font-weight', 600).text(d => `+${Math.round(d.gain)}°`);
  svg.selectAll('.wk').data(weeks).join('text')
    .attr('x', d => x(d.w) + x.bandwidth() / 2).attr('y', 178).attr('text-anchor', 'middle')
    .attr('font-size', 11).attr('fill', '#677086').text(d => `week ${d.w + 1}`);
}

// Exercise minutes against pain on the same day and on the next day.
function drawPain(rows) {
  const same = rows.filter(r => num(r.exercise_minutes) && num(r.pain_0_10)).map(r => [r.exercise_minutes, r.pain_0_10]);
  const next = rows.slice(0, -1).map((r, i) => [r.exercise_minutes, rows[i + 1].pain_0_10]).filter(([a, b]) => num(a) && num(b));
  const rSame = ss.sampleCorrelation(same.map(d => d[0]), same.map(d => d[1]));
  const rNext = ss.sampleCorrelation(next.map(d => d[0]), next.map(d => d[1]));
  document.getElementById('capSame').textContent = `Same day — ${strength(rSame)} (r = ${rSame.toFixed(2)})`;
  document.getElementById('capNext').textContent = `Next day — ${strength(rNext)} (r = ${rNext.toFixed(2)})`;
  scatter('#same', same, '#8a94a8');
  scatter('#next', next, '#d0603a');
  document.getElementById('caution').textContent =
    `${same.length} days is a small sample: read this as a hint to talk about, not as proof. ` +
    `It also cannot say whether exercise causes the pain, or whether other things happened on those days.`;
}

function scatter(sel, pts, colour) {
  const svg = d3.select(sel).html('');
  const x = d3.scaleLinear(d3.extent(pts, d => d[0]), [30, 250]).nice();
  const y = d3.scaleLinear([0, 10], [160, 10]);
  svg.append('g').attr('transform', 'translate(0,160)').call(d3.axisBottom(x).ticks(4)).attr('font-size', 10);
  svg.append('g').attr('transform', 'translate(30,0)').call(d3.axisLeft(y).ticks(5)).attr('font-size', 10);
  svg.selectAll('circle').data(pts).join('circle')
    .attr('cx', d => x(d[0])).attr('cy', d => y(d[1])).attr('r', 4).attr('fill', colour).attr('opacity', 0.75);
  const fit = ss.linearRegressionLine(ss.linearRegression(pts));
  const [x0, x1] = x.domain();
  svg.append('line').attr('x1', x(x0)).attr('y1', y(fit(x0))).attr('x2', x(x1)).attr('y2', y(fit(x1)))
    .attr('stroke', colour).attr('stroke-width', 2.5);
  svg.append('text').attr('x', 250).attr('y', 154).attr('text-anchor', 'end').attr('font-size', 10).attr('fill', '#677086').text('exercise minutes →');
  svg.append('text').attr('x', 34).attr('y', 14).attr('font-size', 10).attr('fill', '#677086').text('pain');
}
</script>
